    const beforeCalls=(await read()).getUserMediaCalls,latest=await latestRequest();
    const ordinal=await page.evaluate(({field,value})=>window.__captureReacquisition.arm(field,value),{field,value});
    const physical=await click(field,expected);diagnosticStage=field+'-change-ack';
