    const operation=await page.evaluate(ordinal=>window.__captureReacquisition.complete(ordinal),ordinal);
    assert.equal(operation.field,field);assert.equal(operation.value,value);assert.equal(operation.getUserMediaCallsDelta,1);assert.equal(operation.oldEndedBeforeAcquisition,true);assert.equal(operation.oldEnded,true);assert.equal(operation.newLive,true);assert.equal(operation.sameDevice,true);assert.equal(operation.allThreeEffectiveSettings,true);assert.equal(operation.authorityCurrent,true);assert.equal(operation.liveTrackCount,1);
