    return {physical,operation};
   }
   const changed=await processing(!previous,previous),restored=await processing(previous,!previous);
   ledger.push({field,outcome:'real-readback-confirmed',physical:changed.physical,changed:!previous,reacquisition:changed.operation,restored:restored.operation,restorePhysical:restored.physical});
  }
