  await click('native-tab',false);r=await nativeRecord({},'native');assert(r.controls.some(v=>v.kind==='native-tab'&&v.checked));assert.equal((await read()).liveTrackCount,1);await page.getByRole('button',{name:'Close tablet',exact:true}).click();assert.equal((await read()).liveTrackCount,1);await page.locator('#microphone').click();await page.waitForFunction(()=>window.__pttAudit.tracks.every(t=>t.readyState==='ended'),undefined,{timeout:15000});assert.equal((await read()).active,false);assert.equal((await read()).getUserMediaCalls,grantBefore+7);const terminal=await page.evaluate(()=>window.__captureReacquisition.summary());assert.equal(terminal.operations.length,6);assert.equal(terminal.pending,false);assert.equal(terminal.unexpectedCalls,0);assert.equal(terminal.observationFailures,0);assert(terminal.operations.every(v=>v.oldEndedBeforeAcquisition&&v.oldEnded&&v.sameDevice&&v.allThreeEffectiveSettings));report.captureWorker.end=await attestCaptureWorker(profile);assert.deepEqual(report.captureWorker.end,worker);report.captureEffects=ledger;await checkpoint('visitor-capture-real-controls-and-readback-complete');
 }catch(error){primaryFailed=true;await retainCaptureFailure({page,directory,report,stage:diagnosticStage});throw error;}finally{await finishCaptureEvidence({report,directory,primaryFailed,saveProofs,retire:async()=>{const reacquisitionRetired=await page.evaluate(()=>{window.__captureAudit.samplePCM=false;try{window.__captureReacquisition?.retire();}finally{try{window.__captureAudit.trusted?.retire();}finally{window.__captureAudit.proofs?.retire();}}return window.__captureReacquisition?window.__captureReacquisition.summary().retired:null;});if(reacquisitionRetired!==null){assert.equal(reacquisitionRetired,true);report.captureReacquisitionRetired=true;}}});}
